function addDemoPhotos(c){
 if(!c.demo||c.demoCatalogLeaf||c.demoVehicleSample)return;const profiles=DEMO_OBJECT_PROFILES[c.category||'cars'];if(!profiles?.length)return;
 const legacyNames={1042:'BMW 5 серии · 530i',1043:'Mercedes-Benz E 200',1044:'Porsche 911 Carrera',1045:'Audi A6 · 45 TFSI',1046:'Toyota Camry · 2.5 AT',1047:'Kia K5 · 2.0 AT'};
 const legacyProfile={1042:0,1043:2,1044:1,1045:0,1046:1,1047:2};
 const untouchedLegacy=legacyNames[c.id]===c.name&&(!c.image||c.image.startsWith('assets/photos/'));
 // Original named examples keep their identity. A mismatched library photo
 // is filtered at display time instead of renaming an E200 into an AMG GT.
 if(Object.hasOwn(legacyNames,c.id)&&legacyNames[c.id]===c.name)return;
 if(c.demoEdited&&!untouchedLegacy)return;
 if(c.image?.startsWith('https://'))return;
 if(c.media?.some(m=>{const url=typeof m==='string'?m:m.url;return url?.startsWith('https://')&&(!c.img||!url.includes(c.img))}))return;
 const p=profiles.find(p=>p.path===c.demoPhotoProfile)||profiles[Object.hasOwn(legacyProfile,c.id)&&c.category==='cars'?legacyProfile[c.id]:Math.abs(c.id)%profiles.length];
 const suffix=c.name.match(/ · (\d+)$/)?.[1];c.name=p.title+(suffix?' · '+suffix:'');c.brand=p.brand||'';c.model=p.title;c.manufacturer=p.brand||null;c.photoExample=true;c.demoPhotoProfile=p.path;c.image=p.path;
 c.media=[{url:p.path+'?view=1',label:'Фрагмент того же фото · демо',crop:'left'},{url:p.path+'?view=2',label:'Крупный фрагмент того же фото · демо',crop:'detail'}];
}
